// Turns seed/lessons/*.json into seed/course.sql, an idempotent upsert of the built-in course.
// Apply with: npm run db:seed:local  /  npm run db:seed:remote
import { readFileSync, readdirSync, writeFileSync } from "node:fs";

const LEVELS = ["A1", "A2", "B1", "B2", "C1"];
const dir = new URL("../seed/lessons/", import.meta.url);
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;

const lines = [
  "-- Generated by scripts/build-seed.mjs from seed/lessons/*.json. Do not edit by hand.",
  "INSERT OR IGNORE INTO users (login, name, role) VALUES ('byocao', 'byocao', 'admin');",
];
let order = 0;
for (const level of LEVELS) {
  const file = readdirSync(dir).find((f) => f === `${level}.json`);
  if (!file) continue;
  for (const l of JSON.parse(readFileSync(new URL(file, dir), "utf8"))) {
    order += 1;
    const content = { title: l.title, summary_vi: l.summary_vi, sentences: l.sentences, vocabulary: l.vocabulary, questions: l.questions };
    lines.push(
      `INSERT INTO lessons (user_id, title, topic, level, content, provider, is_public, slug, category, course_order)
VALUES ((SELECT id FROM users WHERE login = 'byocao'), ${q(l.title)}, ${q(l.topic)}, ${q(l.level)}, ${q(JSON.stringify(content))}, 'course', 1, ${q(l.slug)}, ${q(l.category)}, ${order})
ON CONFLICT(slug) DO UPDATE SET title = excluded.title, topic = excluded.topic, level = excluded.level, content = excluded.content,
  category = excluded.category, course_order = excluded.course_order;`,
    );
  }
}
writeFileSync(new URL("../seed/course.sql", import.meta.url), lines.join("\n") + "\n");
console.log(`seed/course.sql: ${order} lessons`);
